-- PREPARED ONLY. Typed public acceptance and TT-owned application source fence.
-- Whole-worker Send, other sources, derivatives and maintenance remain prerequisites.
set local lock_timeout='2s';set local statement_timeout='30s';
create table person_private.application_accept_frames(
 backend_pid integer not null,transaction_id xid8 not null,kind text not null,after_row jsonb not null,
 primary key(backend_pid,transaction_id)
);
alter table person_private.application_accept_frames enable row level security;
revoke all on person_private.application_accept_frames from public,anon,authenticated,service_role;

