create function person_private.application_intent_semantics(p jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare result jsonb:='{"version":1,"kind":"future"}';k text;v jsonb;
begin
 foreach k in array array['organization_id','linkedin_username','email','follow_up_at','comp_expectation','visa_status','recruiter_profile_id','person_resume_sha256'] loop result:=result||jsonb_build_object(k,p->k);end loop;
 foreach k in array array['preferred_roles','preferred_locations','preferred_workplace'] loop
  select coalesce(jsonb_agg(x order by x collate "C"),'[]') into v from (select distinct value#>>'{}' x from jsonb_array_elements(coalesce(nullif(p->k,'null'),'[]'))) s;
  result:=result||jsonb_build_object(k,v);
 end loop;
 return result;
end$$;

create function person_private.application_source_guard() returns trigger language plpgsql security definer set search_path='' set timezone='UTC' set datestyle='ISO,YMD' as $$
declare f person_private.application_accept_frames;i person_private.intake_mutation_frames;r person_private.application_result_frames;o jsonb:=to_jsonb(old);n jsonb:=to_jsonb(new);
begin
 select * into f from person_private.application_accept_frames where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id();
 if f.backend_pid is not null then
  if tg_op<>'INSERT' or f.after_row is distinct from n then raise exception 'application_source_frame';end if;return new;
 end if;
 if not person_private.normalization_required() then return coalesce(new,old);end if;
 if o->>'organization_id' is distinct from '801865a7-6533-41d2-9c45-e4a90e6ad51a' and n->>'organization_id' is distinct from '801865a7-6533-41d2-9c45-e4a90e6ad51a' then return coalesce(new,old);end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'application_source_isolation';end if;
 if tg_op<>'UPDATE' or old.id is distinct from new.id or old.organization_id is distinct from new.organization_id then raise exception 'application_source_fence';end if;
 -- Frame creators already took controller/work/username locks in that order.
 -- Row guards never acquire those locks after originating business row locks.
 select * into r from person_private.application_result_frames where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id();
 if r.application_id=new.id and r.before_row-'updated_at'=o-'updated_at' and r.after_row-'updated_at'=n-'updated_at' then return new;end if;
 select * into i from person_private.intake_mutation_frames where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id();
 if i.kind='finalize' and i.application_id=new.id and i.before_row-'updated_at'=o-'updated_at' and i.after_row-'updated_at'=n-'updated_at' then return new;end if;
 raise exception 'application_source_fence';
end$$;
-- The existing person_source_statement_gate takes the controller lock even off.
create trigger person_application_source_before before insert or update or delete on public.website_applications for each row execute function person_private.application_source_guard();
create trigger person_application_source_after after insert or update or delete on public.website_applications for each row execute function person_private.application_source_guard();
create function person_private.application_source_no_truncate() returns trigger language plpgsql security definer set search_path='' as $$
begin raise exception 'application_source_truncate';end$$;
create trigger person_application_source_truncate before truncate on public.website_applications for each statement execute function person_private.application_source_no_truncate();
revoke truncate on public.website_applications from public,anon,authenticated,service_role;

-- The typed RPC chooses time only after the username lock. Keep legacy behavior
-- without a frame; do not replace the checked frame's authoritative timestamp.
do $$declare body text;needle text:='  new.created_at:=clock_timestamp();';begin
 body:=pg_get_functiondef('person_private.application_future_accept()'::regprocedure);
 if array_length(string_to_array(body,needle),1)<>2 then raise exception 'application_accept_definition';end if;
 body:=replace(body,'new.source<>''future''','new.source is distinct from ''future''');
 body:=replace(body,needle,'  if not exists(select 1 from person_private.application_accept_frames where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id()) then new.created_at:=clock_timestamp();end if;');execute body;
end$$;

create function public.person_application_accept(p_kind text,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' set timezone='UTC' set datestyle='ISO,YMD' as $$
declare allowed text[]:=array['organization_id','recruiter_profile_id','name','email','linkedin_username','linkedin_url','visa_status','preferred_locations','role_ids','role_titles','resume_path','person_resume_sha256','source','ip','user_agent'];
 k text;x jsonb;semantic jsonb;target public.website_applications;saved public.website_applications;defaults jsonb;org uuid;recruiter uuid;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'application_accept_isolation';end if;
 -- Must precede username, recruiter and FK/business locks, even while disabled.
 perform person_private.transition_lock();
 if p_kind is null or p_kind not in ('apply','referral','future') then raise exception 'application_accept_kind';end if;
 if p_kind='future' then allowed:=allowed||array['follow_up_at','preferred_roles','preferred_workplace','comp_expectation'];end if;
 if not person_private.application_result_keys(p_input,array['organization_id','name','email','linkedin_username','linkedin_url','preferred_locations','role_ids','role_titles'],allowed) or octet_length(p_input::text)>32768 then raise exception 'application_accept_shape';end if;
 foreach k in array allowed loop
  if k=any(array['role_ids','role_titles','preferred_locations','preferred_roles','preferred_workplace']) then
   x:=coalesce(p_input->k,'[]');
   if jsonb_typeof(x) is distinct from 'array' or jsonb_array_length(x)>30 or exists(select 1 from jsonb_array_elements(x) a(v) where jsonb_typeof(v)<>'string' or length(v#>>'{}')>500) then raise exception 'application_accept_list';end if;
  elsif p_input ? k and jsonb_typeof(p_input->k) not in ('string','null') then raise exception 'application_accept_scalar';end if;
 end loop;
 if p_input->>'organization_id' is null or (p_input->>'organization_id') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then raise exception 'application_accept_organization';end if;org:=(p_input->>'organization_id')::uuid;
 if p_input->>'name' is null or length(p_input->>'name')>120 or (p_kind='apply' and length(btrim(p_input->>'name'))=0) or p_input->>'email' is null or length(p_input->>'email')>254 or (p_input->>'email') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'application_accept_identity';end if;
 if p_input->>'linkedin_username' is null or length(p_input->>'linkedin_username') not between 1 and 200 or p_input->>'linkedin_username'<>lower(btrim(p_input->>'linkedin_username')) or not person_private.application_accept_username(p_input->>'linkedin_username') then raise exception 'application_accept_identity';end if;
 if length(p_input->>'linkedin_url')>300 or length(p_input->>'visa_status')>150 or length(p_input->>'user_agent')>500 or length(p_input->>'source')>2400 then raise exception 'application_accept_scalar';end if;
 if (p_kind='future' and p_input->>'source' is distinct from 'future') or (p_kind='referral' and (p_input->>'source' is null or p_input->>'source' not like 'referral: %')) or (p_kind='apply' and p_input->>'source' is not null and p_input->>'source' !~ '^(speculative(; note: .*)?|note: .*)$') then raise exception 'application_accept_source';end if;
 if p_kind<>'apply' and (jsonb_array_length(p_input->'role_ids')<>0 or jsonb_array_length(p_input->'role_titles')<>0) then raise exception 'application_accept_roles';end if;
 if jsonb_array_length(p_input->'role_ids')>3 or jsonb_array_length(p_input->'role_ids')<>jsonb_array_length(p_input->'role_titles') then raise exception 'application_accept_roles';end if;
 if (nullif(p_input->>'resume_path','') is null) is distinct from (nullif(p_input->>'person_resume_sha256','') is null) or
  (p_input->>'resume_path' is not null and (length(p_input->>'resume_path') not between 1 and 240 or p_input->>'resume_path' ~ '(^/|//|(^|/)\.\.?(/|$)|[\\%?#[:space:]])' or p_input->>'person_resume_sha256' !~ '^[a-f0-9]{64}$')) then raise exception 'application_accept_resume';end if;
 if p_kind='referral' and p_input->>'resume_path' is not null then raise exception 'application_accept_resume';end if;
 if p_kind='future' and (p_input->>'follow_up_at' is null or p_input->>'follow_up_at' !~ '^\d{4}-\d{2}-\d{2}$' or length(p_input->>'comp_expectation')>40) then raise exception 'application_accept_preferences';end if;
 if p_input->>'recruiter_profile_id' is not null then
  if p_input->>'recruiter_profile_id' !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then raise exception 'application_accept_recruiter';end if;recruiter:=(p_input->>'recruiter_profile_id')::uuid;
 end if;
 -- Future dedupe and authoritative acceptance time share the existing identity lock.
 if p_kind='future' then perform pg_advisory_xact_lock(72007,hashtext(p_input->>'linkedin_username'));end if;
 perform 1 from public.organizations where id=org for share;if not found then raise exception 'application_accept_organization';end if;
 if recruiter is not null then perform 1 from public.recruiter_profiles where id=recruiter and organization_id=org and published for share;if not found then raise exception 'application_accept_recruiter';end if;end if;
 defaults:=jsonb_build_object('id',gen_random_uuid(),'created_at',clock_timestamp(),'status','queued','person_processing_version',1,'pool_created_person',false,'preferred_roles','[]'::jsonb,'preferred_workplace','[]'::jsonb);
 target:=jsonb_populate_record(null::public.website_applications,defaults||p_input);
 target.linkedin_url:=person_private.application_identity_url(target.linkedin_username);
 if p_kind='future' then
  semantic:=person_private.application_intent_semantics(to_jsonb(target));
  -- Match original immutable inputs, including accepted rows using the earlier
  -- TypeScript JSON hash. Later result/preference edits do not change identity.
  perform 1 from person_private.application_intents j join public.website_applications a on a.id=j.application_id
   where j.organization_id=org and j.linkedin_username=target.linkedin_username and j.input_snapshot->>'source'='future'
    and a.organization_id=org and a.linkedin_username=target.linkedin_username and a.source='future' and a.person_intent_hash=j.intent_hash
    and person_private.application_intent_semantics(j.input_snapshot)=semantic limit 1 for share of a;
  if found then return jsonb_build_object('inserted',false,'id',null);end if;
  target.person_intent_hash:=person_private.intake_hash(semantic);
  -- A tenant legacy editor may have repurposed the old row while retaining its
  -- unique hash. Preserve it, and give the new durable intent its own DB identity.
  if exists(select 1 from public.website_applications a where a.organization_id=org and a.linkedin_username=target.linkedin_username and a.person_intent_hash=target.person_intent_hash) then
   target.person_intent_hash:=person_private.intake_hash(jsonb_build_array('replacement',semantic,target.id));
  end if;
 end if;
 insert into person_private.application_accept_frames values(pg_backend_pid(),pg_current_xact_id(),p_kind,to_jsonb(target));
 insert into public.website_applications select (target).* on conflict(organization_id,linkedin_username,person_intent_hash) do nothing returning * into saved;
 if not found or to_jsonb(saved) is distinct from to_jsonb(target) then raise exception 'application_accept_actual';end if;
 if p_kind='future' and not exists(select 1 from person_private.application_intents where application_id=saved.id and input_snapshot=person_private.application_work_input(to_jsonb(saved))) then raise exception 'application_accept_journal';end if;
 delete from person_private.application_accept_frames where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id();
 return jsonb_build_object('inserted',true,'id',saved.id);
end$$;
revoke all on function person_private.application_accept_username(text),person_private.application_intent_semantics(jsonb),person_private.application_source_guard(),person_private.application_source_no_truncate(),public.person_application_accept(text,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.person_application_accept(text,jsonb) to service_role;
